package com.cju.likelion.cardcollection.reward.service;
import com.cju.likelion.cardcollection.auth.repository.UserRepository; import com.cju.likelion.cardcollection.auth.exception.InvalidCredentialsException; import com.cju.likelion.cardcollection.reward.domain.*; import com.cju.likelion.cardcollection.reward.dto.UserRewardResponse; import com.cju.likelion.cardcollection.reward.repository.UserRewardRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class RewardQueryService { private final UserRepository users; private final UserRewardRepository rewards; public RewardQueryService(UserRepository users,UserRewardRepository rewards){this.users=users;this.rewards=rewards;} @Transactional(readOnly=true) public List<UserRewardResponse> my(UUID id){active(id);return rewards.findByUserId(id).stream().map(UserRewardResponse::from).toList();} @Transactional public UserRewardResponse claim(UUID userId,UUID id){active(userId);UserReward r=rewards.findById(id).filter(x->x.getUser().getId().equals(userId)).orElseThrow(()->new IllegalArgumentException("리워드를 찾을 수 없습니다."));if(r.getReward()==null)throw new IllegalArgumentException("이벤트는 수령 코드 발급 대상이 아닙니다.");if(r.getStatus()!=UserRewardStatus.UNLOCKED)throw new IllegalArgumentException("수령 가능한 상태가 아닙니다.");r.issueClaimCode();return UserRewardResponse.from(r);} private void active(UUID id){users.findByIdAndDeletedAtIsNull(id).orElseThrow(InvalidCredentialsException::new);} }
